.panel { position: relative; background: #f3ede0; box-shadow: 5px 5px 0 rgba(0,120,191,.92); padding: 6px 14px; }
.panel::before { content: ''; position: absolute; inset: -11px; pointer-events: none; background: linear-gradient(#ff48b0,#ff48b0) 0 11px / 7px 1px no-repeat, linear-gradient(#ff48b0,#ff48b0) 11px 0 / 1px 7px no-repeat, linear-gradient(#ff48b0,#ff48b0) 100% 11px / 7px 1px no-repeat, linear-gradient(#ff48b0,#ff48b0) calc(100% - 11px) 0 / 1px 7px no-repeat, linear-gradient(#ff48b0,#ff48b0) 0 calc(100% - 11px) / 7px 1px no-repeat, linear-gradient(#ff48b0,#ff48b0) 11px 100% / 1px 7px no-repeat, linear-gradient(#ff48b0,#ff48b0) 100% calc(100% - 11px) / 7px 1px no-repeat, linear-gradient(#ff48b0,#ff48b0) calc(100% - 11px) 100% / 1px 7px no-repeat; }
.bar { position: relative; width: 240px; height: 22px; background: radial-gradient(circle, rgba(255,72,176,.62) 1.2px, transparent 1.9px) 0 0 / 5px 5px, #f3ede0; }
.bar-fill { position: absolute; inset: 0 auto 0 0; width: 72%; background: #0078bf; mix-blend-mode: multiply; box-shadow: 2px 2px 0 rgba(255,72,176,.85); }
.title { padding: 16px 44px 12px; background: #ffe800; font: 400 56px/1 'Rubik Mono One', monospace; color: #0078bf; text-shadow: 5px 4px 0 rgba(255,72,176,.9); box-shadow: 9px 8px 0 rgba(255,72,176,.9); transform: rotate(-2deg); }
.card-band { background: radial-gradient(circle, #ff48b0 2.3px, transparent 3px) 0 0 / 8px 8px, #ffe800; background-blend-mode: multiply; }
